/*
 * A332820  Integers in the multiplicative subgroup of positive rationals
 *          generated by the products of two consecutive primes and the cubes
 *          of primes. Numbers k for which A048675(k) is a multiple of three.
 * https://oeis.org/A332820
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 71, u16 n <= 71, u32 n <= 71, u64 n <= 71, u128 n <= 71,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A332820: integers n for which the alternating sum of the exponents in
   their prime factorisation is 0 modulo 3.  Equivalently,
   a(n) = (n such that 3 | A048675(n)). */
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

/* ----- Primes -------------------------------------------------------- */
static const idx_t PRIME_SIEVE_LIMIT = 2000000U;   /* enough for n ≲ 10000   */
static uint64_t *prime_list = NULL;
static size_t    prime_cnt  = 0;

/* Build a list of all primes ≤ PRIME_SIEVE_LIMIT (once) */
static void init_primes(void)
{
    if (prime_cnt > 0) return;          /* already built */

    /* Sieve of Eratosthenes */
    bool *is_composite = (bool *)calloc((size_t)PRIME_SIEVE_LIMIT + 1U,
                                        sizeof(bool));
    if (!is_composite) return;          /* memory failure */

    for (uint64_t i = 2; i * i <= PRIME_SIEVE_LIMIT; ++i) {
        if (!is_composite[(size_t)i]) {
            for (uint64_t j = i * i; j <= PRIME_SIEVE_LIMIT; j += i)
                is_composite[(size_t)j] = true;
        }
    }

    /* Count primes */
    for (uint64_t i = 2; i <= PRIME_SIEVE_LIMIT; ++i)
        if (!is_composite[(size_t)i]) ++prime_cnt;

    /* Allocate array */
    prime_list = (uint64_t *)malloc(prime_cnt * sizeof(uint64_t));
    if (!prime_list) {
        free(is_composite);
        return;                           /* memory failure */
    }

    /* Store primes */
    size_t idx = 0;
    for (uint64_t i = 2; i <= PRIME_SIEVE_LIMIT; ++i) {
        if (!is_composite[(size_t)i])
            prime_list[idx++] = i;
    }

    free(is_composite);
}

/* Return the index (0‑based) of prime p in prime_list, or the insertion
   position if p is not present.  Assumes p ≤ PRIME_SIEVE_LIMIT. */
static size_t prime_index(uint64_t p)
{
    size_t lo = 0, hi = prime_cnt;
    while (lo < hi) {
        size_t mid = (lo + hi) >> 1;
        uint64_t q = prime_list[mid];
        if (q == p) return mid;
        if (q < p)  lo = mid + 1;
        else        hi = mid;
    }
    return lo;
}

/* Test whether n is in the subgroup generated by p_i p_{i+1} and p_i^3.
   Equivalently, the alternating sum of the prime exponents in n is 0 mod 3. */
static bool in_subgroup(uint64_t n)
{
    if (n == 1) return true;   /* 1 is always in the subgroup */

    init_primes();

    int8_t alt_mod = 0;                     /* alternating sum modulo 3 */
    uint64_t temp  = n;

    for (size_t pi = 0; pi < prime_cnt &&
                        prime_list[pi] * prime_list[pi] <= temp; ++pi) {
        uint64_t p = prime_list[pi];
        if (temp % p == 0) {
            int exp = 0;
            while (temp % p == 0) {
                temp /= p;
                ++exp;
            }
            int8_t sign = ((pi + 1) & 1) ? 1 : -1;      /* (+1,-1,+1,…) */
            alt_mod = (alt_mod + sign * exp) % 3;
        }
    }

    /* Remaining prime factor, if any */
    if (temp > 1) {
        uint64_t p = temp;
        size_t pi  = prime_index(p);
        if (pi >= prime_cnt || prime_list[pi] != p)
            return false;                 /* should not happen with the limit */
        int exp  = 1;
        int8_t sign = ((pi + 1) & 1) ? 1 : -1;
        alt_mod = (alt_mod + sign * exp) % 3;
    }

    alt_mod = (alt_mod % 3 + 3) % 3;         /* make positive */
    return alt_mod == 0;
}

/* ----- Sequence cache ----------------------------------------------- */
static seq_t *cache     = NULL;
static size_t cache_cap = 0;      /* capacity of cache   */
static size_t cache_len = 0;      /* number of terms stored */
static idx_t  next_candidate = 1; /* next integer to test */

/* Ensure that the cache contains at least n terms */
static void ensure_cache(idx_t n)
{
    while (cache_len < (size_t)n) {
        if (in_subgroup((uint64_t)next_candidate)) {
            if (cache_len == cache_cap) {
                size_t new_cap = cache_cap ? cache_cap * 2 : 128;
                seq_t *tmp = (seq_t *)realloc(cache,
                                               new_cap * sizeof(seq_t));
                if (!tmp) return;               /* allocation failure */
                cache = tmp;
                cache_cap = new_cap;
            }
            cache[cache_len++] = (seq_t)next_candidate;
        }
        ++next_candidate;
    }
}

/* -------------------------------------------------------------- */
/*  Public function required by the platform                       */
seq_t a(idx_t n)
{
    if (n == 0) return 0;                  /* undefined, avoid underflow */
    ensure_cache(n);
    return cache[(size_t)(n - 1)];
}
